sql.oracle:
CREATE OR REPLACE FUNCTION FN_TRQ_DIAS_ABERTO (p_dt_abertura IN DATE, p_dt_encerramento IN DATE)
RETURN NUMBER
IS
BEGIN
IF p_dt_abertura IS NULL THEN
RETURN NULL;
END IF;
RETURN TRUNC(NVL(p_dt_encerramento, SYSDATE)) - TRUNC(p_dt_abertura);
END;

sql.mssql:
CREATE FUNCTION FN_TRQ_DIAS_ABERTO (@dt_abertura DATETIME, @dt_encerramento DATETIME)
RETURNS INT
AS
BEGIN
IF @dt_abertura IS NULL
RETURN NULL;
RETURN DATEDIFF(DAY, @dt_abertura, ISNULL(@dt_encerramento, GETDATE()));
END;
